<template>
  <v-dialog :model-value="modelValue" @update:model-value="$emit('update:modelValue',$event)" max-width="1500" width="97vw" scrollable persistent>
    <v-card rounded="xl"><v-card-title class="pa-5 d-flex align-center justify-space-between"><span>{{ quotation ? `Edit Quotation ${quotation.quotation_number}` : 'Create Quotation' }}</span><v-btn icon="mdi-close" variant="text" :disabled="saving" @click="$emit('update:modelValue',false)" /></v-card-title>
      <v-card-text><v-progress-linear v-if="loading" indeterminate /><v-alert v-if="error" type="error" variant="tonal" class="mb-4">{{ error }}</v-alert>
        <v-form ref="form" validate-on="submit">
          <h3 class="text-h6 mb-4">Header Information</h3>
          <v-row><v-col cols="12" md="4"><v-select v-model="recipientType" :items="[{title:'Existing lead',value:'lead'},{title:'Existing customer',value:'customer'},{title:'New prospect',value:'manual'}]" label="Quote for" variant="outlined" @update:model-value="clearRecipient" /></v-col>
            <v-col v-if="recipientType==='lead'" cols="12" md="8"><v-autocomplete v-model="data.lead_id" :items="options.leads" item-title="company_name" item-value="id" label="Lead" variant="outlined" :rules="[v=>!!v || 'Select a lead']" @update:model-value="selectLead" /></v-col>
            <v-col v-if="recipientType==='customer'" cols="12" md="8"><v-autocomplete v-model="data.customer_id" :items="options.customers" item-title="name" item-value="id" label="Customer" variant="outlined" :rules="[v=>!!v || 'Select a customer']" @update:model-value="selectCustomer" /></v-col>
            <v-col cols="12" md="6"><v-text-field v-model="data.recipient_name" label="Customer / Company Name *" :rules="[v=>!!v?.trim() || 'Recipient name is required']" maxlength="150" variant="outlined" /></v-col>
            <v-col cols="12" md="6"><v-text-field v-model="data.contact_person" label="Contact Person" variant="outlined" maxlength="150" /></v-col>
            <v-col cols="12" md="4"><v-text-field v-model="data.quotation_date" label="Quotation Date *" type="date" variant="outlined" :rules="[v=>!!v || 'Choose a date']" /></v-col>
            <v-col cols="12" md="4"><v-text-field v-model="data.valid_until" label="Valid Until" type="date" variant="outlined" /></v-col>
            <v-col cols="12" md="4"><v-autocomplete v-model="data.assigned_user_id" :items="options.staff" item-title="name" item-value="id" label="Sales Executive" clearable variant="outlined" /></v-col>
            <v-col cols="12" md="6"><v-text-field v-model="data.email" label="Email" type="email" variant="outlined" maxlength="100" /></v-col><v-col cols="12" md="6"><v-text-field v-model="data.phone" label="Phone / WhatsApp" variant="outlined" maxlength="30" /></v-col>
            <v-col cols="12"><v-text-field v-model="data.address" label="Address" variant="outlined" maxlength="2000" /></v-col><v-col cols="12" md="6"><v-text-field v-model="data.customer_reference" label="Customer Reference" variant="outlined" maxlength="150" /></v-col><v-col cols="12" md="6"><v-text-field v-model="data.branch" label="Branch" variant="outlined" maxlength="150" /></v-col>
          </v-row>
          <div class="d-flex justify-space-between align-center my-4"><h3 class="text-h6">Requested Services</h3><v-btn prepend-icon="mdi-plus" variant="tonal" color="primary" size="small" @click="addItem">Add Service</v-btn></div>
          <ServiceBundlePicker v-if="modelValue && !loading" kind="quotation" :disabled="saving" :pricing-category="options.customers.find(row=>String(row.id)===String(data.customer_id))?.pricing_category || 'Normal'" @add="addTemplate" @busy="templateBusy=$event" />
          <div class="quotation-lines"><v-table density="compact"><thead><tr><th>Service</th><th>Description</th><th>Qty</th><th>Cost</th><th>Service Charge</th><th>Rate</th><th>Processing Time</th><th>Amount</th><th /></tr></thead><tbody><tr v-for="(item,index) in data.items" :key="index"><td style="min-width:210px"><v-combobox :model-value="item.service_name" :items="options.services" item-title="name" item-value="id" label="Service *" placeholder="Select or type a service" density="compact" variant="outlined" hide-details clearable @update:model-value="value=>selectService(item,value)" /></td><td style="min-width:170px"><v-textarea v-model="item.description" rows="2" density="compact" variant="outlined" hide-details /></td><td><v-text-field v-model.number="item.quantity" type="number" min="1" step="1" density="compact" variant="outlined" hide-details style="width:80px" /></td><td><v-text-field v-model.number="item.cost" type="number" min="0" step="0.01" density="compact" variant="outlined" hide-details style="width:100px" @update:model-value="reprice(item)" /></td><td><v-text-field v-model.number="item.service_charge" type="number" min="0" step="0.01" density="compact" variant="outlined" hide-details style="width:105px" @update:model-value="reprice(item)" /></td><td><v-text-field v-model.number="item.rate" type="number" min="0" step="0.01" density="compact" variant="outlined" hide-details style="width:100px" /></td><td><v-text-field v-model="item.expected_processing_time" placeholder="e.g. 3 days" density="compact" variant="outlined" hide-details style="width:130px" /></td><td class="text-no-wrap">{{ money(lineTotal(item)) }}</td><td><v-btn icon="mdi-close" variant="text" color="error" size="small" :disabled="data.items.length===1" @click="data.items.splice(index,1)" /></td></tr></tbody></v-table></div>
          <v-row class="mt-5"><v-col cols="12" md="8"><v-textarea v-model="data.notes" label="Customer-facing Notes" rows="2" variant="outlined" /><v-textarea v-model="data.internal_remarks" label="Internal Remarks (not printed)" rows="2" variant="outlined" /></v-col><v-col cols="12" md="4"><p class="d-flex justify-space-between mb-3"><span>Subtotal</span><strong>{{ money(subtotal) }}</strong></p><v-text-field v-model.number="data.discount" label="Discount (AED)" type="number" min="0" step="0.01" variant="outlined" density="compact" /><v-text-field v-model.number="data.tax_rate" label="VAT %" type="number" min="0" max="100" :disabled="!options.tax_enabled" variant="outlined" density="compact" /><p class="d-flex justify-space-between mb-3"><span>VAT</span><strong>{{ money(tax) }}</strong></p><p class="d-flex justify-space-between text-h6"><span>Total</span><strong>{{ money(total) }}</strong></p><v-select v-model="data.template_style" :items="options.styles" label="PDF Template" variant="outlined" density="compact" class="mt-4" /></v-col></v-row>
          <v-expansion-panels class="my-4" multiple :model-value="[0,1]"><v-expansion-panel><v-expansion-panel-title>Bank Account Details</v-expansion-panel-title><v-expansion-panel-text><v-row><v-col v-for="field in bankFields" :key="field.key" cols="12" md="6"><v-text-field v-model="data.bank_details[field.key]" :label="field.label" maxlength="150" variant="outlined" /></v-col></v-row></v-expansion-panel-text></v-expansion-panel><v-expansion-panel><v-expansion-panel-title>Payment Terms & Terms and Conditions</v-expansion-panel-title><v-expansion-panel-text><v-textarea v-model="data.payment_terms" label="Payment Terms" rows="3" maxlength="5000" variant="outlined" /><v-textarea v-model="data.terms" label="Terms and Conditions" rows="5" maxlength="5000" variant="outlined" /><v-btn v-if="auth.can('settings','write')" variant="tonal" size="small" :loading="savingDefaults" @click="saveDefaults">Save bank details and terms as workspace defaults</v-btn></v-expansion-panel-text></v-expansion-panel></v-expansion-panels>
        </v-form>
      </v-card-text><v-card-actions class="pa-5"><v-spacer /><v-btn :disabled="saving" @click="$emit('update:modelValue',false)">Cancel</v-btn><v-btn color="primary" variant="flat" :loading="saving" :disabled="loading || templateBusy" @click="save">{{ quotation?'Save as Draft':'Create Quotation' }}</v-btn></v-card-actions></v-card>
  </v-dialog>
</template>
<script setup>
import {useAuthStore} from '~/stores/auth';import {useUIStore} from '~/stores/ui';
import {appendBundleLines} from '~/utils/serviceBundleLines.mjs';
import ServiceBundlePicker from '~/components/services/ServiceBundlePicker.vue';
const templateBusy=ref(false);
const props=defineProps({modelValue:Boolean,quotation:Object,seed:Object,initialLeadId:[String,Number]});const emit=defineEmits(['update:modelValue','saved']);
const auth=useAuthStore(),ui=useUIStore(),{$api}=useNuxtApp();
const form=ref(null),loading=ref(false),saving=ref(false),savingDefaults=ref(false),error=ref(''),recipientType=ref('customer');
const options=reactive({customers:[],leads:[],services:[],staff:[],styles:['classic','modern','compact','minimal'],defaults:{},tax_enabled:false});
const data=reactive({items:[],bank_details:{}});
const bankFields=[{key:'bank_name',label:'Bank Name'},{key:'account_name',label:'Account Holder Name'},{key:'account_number',label:'Account Number'},{key:'iban',label:'IBAN'},{key:'swift',label:'SWIFT / BIC'},{key:'branch',label:'Bank Branch'}];
const round=value=>Math.round(Number(value || 0)*100)/100;
const lineTotal=item=>round(Number(item.rate || 0)*Number(item.quantity || 0));
const subtotal=computed(()=>round(data.items.reduce((sum,item)=>sum+lineTotal(item),0)));
const tax=computed(()=>round(Math.max(0,subtotal.value-Number(data.discount || 0))*Number(data.tax_rate || 0)/100));
const total=computed(()=>round(subtotal.value-Number(data.discount || 0)+tax.value));
const money=value=>'AED '+Number(value || 0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
function addItem(){data.items.push({service_type_id:null,service_name:'',description:'',quantity:1,cost:0,service_charge:0,rate:0,expected_processing_time:''});}
function addTemplate(items){try{data.items=appendBundleLines(data.items,items,100);}catch(e){error.value=e.message;}}
function reprice(item){item.rate=round(Number(item.cost || 0)+Number(item.service_charge || 0));}
function selectService(item,value){const service=value && typeof value==='object'?options.services.find(row=>String(row.id)===String(value.id)):null;item.service_type_id=service?.id ?? null;item.service_name=service?.name ?? (typeof value==='string'?value:'');if(!service)return;item.cost=Number(service.cost_price || 0);item.service_charge=Number(service.service_charge || 0);reprice(item);}
function clearRecipient(){data.lead_id=null;data.customer_id=null;data.recipient_name='';data.contact_person='';data.email='';data.phone='';data.address='';}
function selectLead(id){const lead=options.leads.find(row=>row.id===id);if(!lead)return;data.customer_id=null;data.recipient_name=lead.company_name;data.contact_person=lead.name || '';data.email=lead.email || '';data.phone=lead.phone || '';}
function selectCustomer(id){const customer=options.customers.find(row=>row.id===id);if(!customer)return;data.lead_id=null;data.recipient_name=customer.name;data.email=customer.email || '';data.phone=customer.phone_whatsapp || '';data.address=customer.address || '';}
watch(()=>props.modelValue,async value=>{
  if(!value)return;loading.value=true;error.value='';
  try{Object.assign(options,(await $api.get('/quotations/options')).data.data);const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Dubai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
    Object.assign(data,{lead_id:null,customer_id:null,recipient_name:'',contact_person:'',email:'',phone:'',address:'',quotation_date:day,valid_until:'',customer_reference:'',branch:'',assigned_user_id:auth.user?.id,items:[],discount:0,tax_rate:0,template_style:options.default_style || 'classic',notes:'',internal_remarks:'',bank_details:{...options.defaults.bank_details},payment_terms:options.defaults.payment_terms || '',terms:options.defaults.terms || ''});
    if(props.quotation || props.seed){Object.assign(data,JSON.parse(JSON.stringify(props.quotation || props.seed)));if(props.seed){data.quotation_date=day;data.valid_until='';}recipientType.value=data.lead_id?'lead':data.customer_id?'customer':'manual';
      if(data.lead_id && !options.leads.some(row=>row.id===data.lead_id))options.leads.push({id:data.lead_id,company_name:data.recipient_name,name:data.contact_person,email:data.email,phone:data.phone});
      if(data.customer_id && !options.customers.some(row=>row.id===data.customer_id))options.customers.push({id:data.customer_id,name:data.recipient_name,email:data.email,phone_whatsapp:data.phone,address:data.address});
    }
    else{recipientType.value=props.initialLeadId?'lead':'customer';addItem();if(props.initialLeadId){data.lead_id=Number(props.initialLeadId);selectLead(data.lead_id);}}
    await nextTick();form.value?.resetValidation();
  }catch(e){error.value=e.response?.data?.message || 'Unable to load quotation options.';}finally{loading.value=false;}
});
async function save(){if(saving.value || templateBusy.value)return;const validation=await form.value?.validate();if(!validation?.valid)return;saving.value=true;error.value='';try{const response=await $api[props.quotation?'put':'post'](props.quotation?`/quotations/${props.quotation.id}`:'/quotations',data);emit('saved',response.data.data);emit('update:modelValue',false);}catch(e){error.value=e.response?.data?.message || 'Unable to save quotation.';}finally{saving.value=false;}}
async function saveDefaults(){savingDefaults.value=true;try{await $api.put('/quotations/defaults',{bank_details:data.bank_details,payment_terms:data.payment_terms,terms:data.terms});ui.showSuccess('Quotation defaults saved.');}catch(e){error.value=e.response?.data?.message || 'Unable to save defaults.';}finally{savingDefaults.value=false;}}
</script>
<style scoped>.quotation-lines{overflow-x:auto}.quotation-lines td{padding:12px 6px!important;vertical-align:top}</style>
